def _source_root(path, root=None):
    from pathlib import Path
    if root is not None:
        return Path(root).absolute()
    normal = Path(path).absolute()
    # Task 20262780: match the full owner before its trailing source component.
    # Keep lexical copy identity: owner and per-file links may omit one input.
    domains = {Path(owner).parts for owner in PRODUCTION_ROOTS}
    relatives = [relative for pair in _SOURCE_MOVE_PINS for relative in pair]
    relatives += [destination for origin, ident, destination in _SOURCE_FRAGMENT_PINS]
    for relative in relatives:
        parts = Path(relative).parts
        end = parts.index('source') + 1 if 'source' in parts else 1
        domains.add(parts[:end])
    for parts in sorted(domains, key=lambda value: (-len(value), value)):
        for ancestor in (normal, *normal.parents):
            if ancestor.parts[-len(parts):] == parts:
                return ancestor.parents[len(parts) - 1]
    return None


def physical_source_path(path, *, root=None):
    from pathlib import Path
    path = Path(path).absolute()
    root = _source_root(path, root)
    for old, new in SOURCE_MOVES:
        if root is not None and path == root / old:
            return path if path.exists() else root / new
    return path


def logical_source_paths(directory, pattern, *, root=None):
    from pathlib import Path
    directory = Path(directory)
    normal = directory.absolute()
    root = _source_root(normal, root)
    result = []
    for old, new in _SOURCE_MOVE_PINS:
        if root is not None:
            logical = root / old
            if logical.is_relative_to(normal) and logical.match(pattern):
                _source_validity.append((
                    sum(a == old for a, b in SOURCE_MOVES) == 1
                    and sum(a == old and b == new for a, b in SOURCE_MOVES) == 1
                    and logical.exists() != (root / new).exists()))
    for path in directory.rglob(pattern):
        if not any(root is not None and path.absolute() == root / new for old, new in SOURCE_MOVES):
            result.append(path)
    for old, new in SOURCE_MOVES:
        if root is not None:
            logical = root / old
            if logical.is_relative_to(normal) and logical.match(pattern) and (root / new).exists():
                result.append(directory / logical.relative_to(normal))
    return result


def _original_fragment(text, fragment):
    import hashlib
    if fragment['id'] == 'prepared_topology_pen_activation:UT1':
        text = text.replace('import toolpipe.state_paths : getStatePath;', 'import popup_state : getStatePath;')
    if fragment['id'] == 'ai3d.worker_manager:UT9':
        text = text.replace('enum repoRoot  = dirName(dirName(dirName(dirName(dirName(dirName(dirName(dirName(__FILE_FULL_PATH__))))))));',
                            'enum repoRoot  = dirName(dirName(dirName(__FILE_FULL_PATH__)));')
    if fragment['id'] == 'remesh.remesh_job:helper2':
        text = text.replace('version (unittest) public void tryRemove(string path)',
                            'version (unittest) private void tryRemove(string path)')
    declarations = ()
    if fragment['id'] == 'drag:helper2':
        declarations = ('immutable Cam[] corpusCams =', 'Viewport corpusViewport(',
                        'float vlen(', 'Vec3 exactPlaneDelta(')
    elif fragment['id'] == 'snap_render:helper6':
        declarations = ('float[16] t0619Matrix(', 'Viewport t0619Viewport(',
                        'Mesh t0619Mesh(', 'void t0619DrawnPx(', 'void t0619IdentityPx(',
                        'double t0619Dist(', 'ItemXform t0619Xf(', 'void t0619PxUnder(',
                        'Mesh t0619BgMeshA(', 'Mesh t0619BgMeshB(', 'void t0619InstallPrimary(')
    if any('\n    public ' + declaration in text for declaration in declarations):
        if any('\n    public ' + declaration not in text
               or '\n    private ' + declaration in text for declaration in declarations):
            return '', 0
        for declaration in declarations:
            text = text.replace('\n    public ' + declaration, '\n    private ' + declaration)
    encoded = text.encode('utf-8')
    prefix = fragment['prefix'].encode('utf-8')
    offset, matches, result = 0, 0, []
    while offset < len(encoded):
        found = encoded.find(prefix, offset)
        if found < 0:
            break
        part = encoded[found:found + fragment['length']]
        if len(part) == fragment['length'] and hashlib.sha256(part).hexdigest() == fragment['sha']:
            matches += 1
            result.append(part.decode('utf-8'))
        offset = found + 1
    return '\n'.join(result), matches




def _without_carrier_imports(source):
    import re
    # Only the named extracted imports are new; all original imports stay.
    names = '|'.join(re.escape(name) for name in _SOURCE_CARRIER_MODULES)
    return re.sub(r'\bimport\s+(?:' + names + r')\b[^;]*;',
                  lambda match: ''.join('\n' if c == '\n' else ' ' for c in match.group()), source)


def read_source_text(path, *, root=None, **kwargs):
    from pathlib import Path
    path = Path(path).absolute()
    root = _source_root(path, root)
    for old, new in _SOURCE_MOVE_PINS:
        if root is not None and path == root / old:
            _source_validity.append((sum(a == old for a, b in SOURCE_MOVES) == 1
                and sum(a == old and b == new for a, b in SOURCE_MOVES) == 1))
            _source_validity.append(all(
                sum(f['source'] == origin and f['id'] == ident and f['destination'] == destination
                    for f in SOURCE_FRAGMENTS) == 1
                for origin, ident, destination in _SOURCE_FRAGMENT_PINS if origin == old))
    for old, new in SOURCE_MOVES:
        if root is None or path != root / old:
            continue
        destination = root / new
        before, after = path.exists(), destination.exists()
        text = (path if before else destination).read_text(**kwargs)
        if not before:
            text = _without_carrier_imports(text)
            if old == 'source/drag.d':
                context = 'version (unittest) {\n    import std.math : PI, sin, cos, tan;\n}\n'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '')
            if old == 'source/snap_render.d':
                context = 'version (unittest) {\n    import math     : lookAt, perspectiveMatrix, transformPoint;\n    import document : ItemXform, primaryModelSpaceResolver;\n    import std.format : format;\n}\n'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '')
            if old == 'source/ai/state.d':
                context = 'import toolpipe.state_paths : setStatePath;'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, 'import popup_state : setStatePath;')
            if old == 'source/ai3d/worker_manager.d':
                context = '        enum repoRoot = dirName(dirName(dirName(dirName(dirName(__FILE_FULL_PATH__)))));'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '        enum repoRoot = dirName(dirName(dirName(__FILE_FULL_PATH__)));')
            if old == 'source/remesh/remesh_job.d':
                context = 'version (unittest) public void tryRemove(string path)'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, 'version (unittest) private void tryRemove(string path)')
            if old == 'source/coord_rounding.d':
                text = text.replace('import toolpipe.state_paths : setStatePath;', 'import popup_state : setStatePath;')
        _source_validity.append(before != after)
        for fragment in SOURCE_FRAGMENTS:
            if fragment['source'] != old:
                continue
            if before:
                original, matches = _original_fragment(text, fragment)
            else:
                carrier = root / fragment['destination']
                original, matches = _original_fragment(carrier.read_text(**kwargs), fragment) if carrier.exists() else ('', 0)
                if fragment['destination'] != new:
                    text += '\n' + original
            _source_validity.append(matches == 1)
        return text
    return path.read_text(**kwargs)


def source_input_start():
    return len(_source_validity)


def source_inputs_intact(first):
    return all(_source_validity[first:])
